import hashlib
import json
import os
import stat
from pathlib import Path

import pytest

from core import rpgm_plugins as rp
from core.rpgm_plugins import PluginListError, StalePluginList

MV_HEADER = (
    "// Generated by RPG Maker.\n// Do not edit this file directly.\nvar $plugins =\n"
)
MZ_MANAGERS = (
    "PluginManager.setup = function(plugins) {\n"
    "    for (const plugin of plugins) {\n"
    "        const pluginName = Utils.extractFileName(plugin.name);\n"
    "        if (plugin.status && !this._scripts.includes(pluginName)) {\n"
)
OLD_MZ_MANAGERS = "if (plugin.status && !this._scripts.includes(plugin.name)) {\n"
MV_MANAGERS = "if (plugin.status && !this._scripts.contains(plugin.name)) {\n"


def entry(name: str, status: bool = True, **extra: object) -> dict[str, object]:
    return {
        "name": name,
        "status": status,
        "description": extra.pop("description", ""),
        "parameters": extra.pop("parameters", {}),
    }


def plugins_text(entries: list[dict[str, object]], newline: str = "\n") -> str:
    rows = [
        json.dumps(item, ensure_ascii=False, separators=(",", ":")) for item in entries
    ]
    body = ("," + newline).join(rows)
    text = MV_HEADER + "[" + newline + body + newline + "];" + newline
    return text.replace("\n", newline)


def make_game(
    tmp_path: Path,
    entries: list[dict[str, object]],
    engine: str = "mz",
    files: tuple[str, ...] | None = None,
    www: bool = False,
) -> Path:
    root = tmp_path / "game" / ("www" if www else "")
    js = root / "js"
    (js / "plugins").mkdir(parents=True, exist_ok=True)
    (root / "data").mkdir(parents=True, exist_ok=True)
    (root / "data" / "System.json").write_text("{}", encoding="utf-8")
    if engine == "mz":
        (js / "rmmz_managers.js").write_text(MZ_MANAGERS, encoding="utf-8")
    elif engine == "oldmz":
        (js / "rmmz_managers.js").write_text(OLD_MZ_MANAGERS, encoding="utf-8")
    elif engine == "mv":
        (js / "rpg_managers.js").write_text(MV_MANAGERS, encoding="utf-8")
    (js / "plugins.js").write_text(plugins_text(entries), encoding="utf-8")
    names = files if files is not None else tuple(str(e["name"]) for e in entries)
    for name in names:
        path = js / "plugins" / (name + ".js")
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text("// plugin\n", encoding="utf-8")
    return root


def write_plugin(root: Path, name: str, header: str) -> None:
    path = root / "js" / "plugins" / (name + ".js")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(header, encoding="utf-8")


def by_name(state: dict[str, object]) -> dict[str, dict[str, object]]:
    return {str(e["name"]): e for e in state["entries"]}  # pyright: ignore[reportGeneralTypeIssues]


def codes(item: dict[str, object]) -> list[str]:
    return [str(issue["code"]) for issue in item["issues"]]  # pyright: ignore[reportGeneralTypeIssues]


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


# ── 1.1 Strict reader ──


def test_reads_mv_and_mz_layouts():
    mv = plugins_text([entry("A"), entry("B", False)])
    parsed = rp.parse_text(mv)
    assert [(e.name, e.enabled) for e in parsed.entries] == [("A", True), ("B", False)]
    mz = (
        "// Generated by RPG Maker.\nvar $plugins =\n[\n"
        + json.dumps(entry("C"))
        + "\n];\n"
    )
    assert rp.parse_text(mz).entries[0].name == "C"
    for variant in (
        "$plugins=[]",
        "let $plugins = [];",
        "const/*x*/$plugins/*y*/=/*z*/[] // end",
    ):
        assert rp.parse_text(variant).entries == ()


def test_empty_array_bom_crlf_japanese_and_brackets_in_comments():
    assert rp.parse_text("var $plugins = [];").entries == ()
    text = "\ufeff// [patched] ]]\r\n/* [x] */" + plugins_text(
        [entry("日本", description="説明 [括弧]")], "\r\n"
    )
    parsed = rp.parse_bytes(text.encode("utf-8"))
    assert parsed.entries[0].name == "日本"
    assert parsed.entries[0].description == "説明 [括弧]"


def test_status_inside_a_parameter_is_not_the_status():
    text = plugins_text(
        [entry("A", False, parameters={"note": '"status":true', "status": "true"})]
    )
    parsed = rp.parse_text(text)
    item = parsed.entries[0]
    assert item.enabled is False
    assert text[item.status_start : item.status_end] == "false"


@pytest.mark.parametrize(
    ("text", "reason"),
    [
        ("var $plugins = [];\nfoo();", "code after"),
        ('var $plugins = [{"name":"A","status":true},];', "not valid JSON"),
        ("var $plugins = [{'name':'A','status':true}];", "not valid JSON"),
        ('var $plugins = [{"name":"A\\q","status":true}];', "not valid JSON"),
        ("/* open\nvar $plugins = [];", "not closed"),
        ('var $plugins = [{"name":"A","status":true,"p":NaN}];', "NaN"),
        (
            'var $plugins = [{"name":"A","status":true,"status":false}];',
            "more than one",
        ),
        ('var $plugins = [{"name":"A","status":"true"}];', "not true or false"),
        ('var $plugins = [{"name":"A"}];', "no true/false"),
        ('var $plugins = [{"status":true}];', "no single text name"),
        ('var $plugins = [{"name":1,"status":true}];', "no single text name"),
        ('var $plugins = ["A"];', "not an object"),
        ("foo(); var $plugins = [];", "does not start"),
        ("var $pluginsX = [];", "does not start"),
        ("var $plugins == [];", "does not start"),
        ("var $plugins = {};", "not set to an array"),
    ],
)
def test_unreadable_lists_give_a_reason(text, reason):
    with pytest.raises(PluginListError, match=reason):
        _ = rp.parse_text(text)


def test_deep_nesting_non_utf8_and_too_large():
    deep = '{"a":' * 100000 + "1" + "}" * 100000
    text = 'var $plugins = [{"name":"A","status":true,"p":' + deep + "}];"
    with pytest.raises(PluginListError):
        _ = rp.parse_text(text)
    with pytest.raises(PluginListError, match="not UTF-8"):
        _ = rp.parse_bytes(b"var $plugins = [\xff];")
    with pytest.raises(PluginListError, match="4 MiB"):
        _ = rp.parse_bytes(b" " * (rp.LIST_LIMIT + 1))


def test_missing_and_too_large_file_in_load(tmp_path):
    root = make_game(tmp_path, [entry("A")])
    (root / "js" / "plugins.js").unlink()
    state = rp.load_plugins(str(root))
    assert state["readable"] is False
    assert "not found" in str(state["reason"])
    assert state["revision"] == ""
    (root / "js" / "plugins.js").write_bytes(b" " * (rp.LIST_LIMIT + 1))
    state = rp.load_plugins(str(root))
    assert state["readable"] is False
    assert "4 MiB" in str(state["reason"])


# ── 1.2 Safe paths ──


@pytest.mark.parametrize(
    "name", ["../../../outside", "/etc/passwd", "C:/x", "a\\b", "a\0b", "a/../b", ""]
)
def test_unsafe_names(tmp_path, name):
    root = make_game(tmp_path, [entry(name, False)], files=())
    item = rp.load_plugins(str(root))["entries"][0]  # pyright: ignore[reportIndexIssue]
    assert codes(item) == ["unsafe_name"]
    assert item["can_enable"] is False
    with pytest.raises(PluginListError, match="cannot be switched on"):
        _ = rp.set_plugin_enabled(
            str(root),
            0,
            True,
            rp.load_plugins(str(root))["revision"],  # pyright: ignore[reportArgumentType]
        )


@pytest.mark.skipif(not hasattr(os, "symlink"), reason="no symlinks")
def test_symlinks_that_leave_the_root(tmp_path):
    outside = tmp_path / "outside"
    outside.mkdir()
    (outside / "Evil.js").write_text("/*:\n * @base X\n */", encoding="utf-8")
    root = make_game(tmp_path, [entry("Evil"), entry("Inside")], files=("Inside",))
    os.symlink(outside / "Evil.js", root / "js" / "plugins" / "Evil.js")
    os.symlink(
        root / "js" / "plugins" / "Inside.js", root / "js" / "plugins" / "Link.js"
    )
    state = rp.load_plugins(str(root))
    assert codes(by_name(state)["Evil"]) == ["unsafe_name"]
    assert codes(by_name(state)["Inside"]) == []

    # A symlinked js folder that leaves the data root.
    other = tmp_path / "other"
    other.mkdir()
    (root / "js").rename(other / "js")
    os.symlink(other / "js", root / "js")
    state = rp.load_plugins(str(root))
    assert state["readable"] is False
    assert "outside" in str(state["reason"])
    with pytest.raises(PluginListError, match="outside"):
        _ = rp.set_plugin_enabled(str(root), 0, False, "")


@pytest.mark.skipif(not hasattr(os, "symlink"), reason="no symlinks")
def test_symlinked_js_folder_inside_the_root_is_allowed(tmp_path):
    root = make_game(tmp_path, [entry("A")])
    (root / "js").rename(root / "real_js")
    os.symlink(root / "real_js", root / "js")
    assert rp.load_plugins(str(root))["readable"] is True


@pytest.mark.skipif(not hasattr(os, "symlink"), reason="no symlinks")
def test_symlinked_list_and_backup(tmp_path):
    root = make_game(tmp_path, [entry("A")])
    js = root / "js"
    (js / "plugins.js").rename(js / "real.js")
    os.symlink(js / "real.js", js / "plugins.js")
    state = rp.load_plugins(str(root))
    assert state["readable"] is False
    assert "symbolic link" in str(state["reason"])
    with pytest.raises(PluginListError, match="symbolic link"):
        _ = rp.set_plugin_enabled(str(root), 0, False, "")
    with pytest.raises(PluginListError, match="symbolic link"):
        _ = rp.restore_plugins(str(root), "", True)
    assert (js / "real.js").read_text(encoding="utf-8") == plugins_text([entry("A")])

    (js / "plugins.js").unlink()
    (js / "real.js").rename(js / "plugins.js")
    os.symlink(js / "real.js", js / "plugins.js.wlib-backup")
    state = rp.load_plugins(str(root))
    assert state["backup"] == {
        "state": "invalid",
        "reason": "The backup is a symbolic link",
    }
    before = (js / "plugins.js").read_bytes()
    with pytest.raises(PluginListError, match="no backup can be made"):
        _ = rp.set_plugin_enabled(str(root), 0, False, str(state["revision"]))
    assert (js / "plugins.js").read_bytes() == before


@pytest.mark.skipif(not hasattr(os, "mkfifo"), reason="no FIFOs")
def test_fifo_does_not_block(tmp_path):
    root = make_game(tmp_path, [entry("Pipe")], files=())
    js = root / "js"
    os.mkfifo(js / "plugins" / "Pipe.js")
    assert codes(by_name(rp.load_plugins(str(root)))["Pipe"]) == ["missing_file"]
    os.mkfifo(js / "plugins.js.wlib-backup")
    assert rp.load_plugins(str(root))["backup"]["state"] == "invalid"  # pyright: ignore[reportIndexIssue]
    (js / "plugins.js").unlink()
    os.mkfifo(js / "plugins.js")
    state = rp.load_plugins(str(root))
    assert state["readable"] is False
    assert "not a regular file" in str(state["reason"])


