# ── 1.4 MZ header checks ──


def header(*tags: str, lang: str = "", newline: str = "\n") -> str:
    body = newline.join(f" * {tag}" for tag in tags)
    return f"/*:{lang}{newline} * @target MZ{newline}{body}{newline} */{newline}"


def test_missing_dependency_language_blocks_and_struct(tmp_path):
    root = make_game(
        tmp_path, [entry("CoreEngine", False), entry("User"), entry("Other")]
    )
    write_plugin(
        root,
        "User",
        header("@base CoreEngine")
        + header("@base CoreEngine", lang="ja")
        + "/*~struct~Thing:\n * @base Other2\n */\n",
    )
    items = by_name(rp.load_plugins(str(root)))
    issues = items["User"]["issues"]
    assert issues == [  # pyright: ignore[reportGeneralTypeIssues]
        {"code": "missing_dependency", "level": "warning", "names": ["CoreEngine"]}
    ]


def test_crlf_closing_tag_folder_names_and_self_reference(tmp_path):
    root = make_game(
        tmp_path, [entry("Author/CoreEngine"), entry("User"), entry("Self")]
    )
    write_plugin(
        root, "User", "/*:\r\n * @base CoreEngine\r\n * @base Author/CoreEngine */\r\n"
    )
    write_plugin(root, "Self", header("@base Self", "@orderAfter Self"))
    items = by_name(rp.load_plugins(str(root)))
    assert codes(items["User"]) == []
    assert codes(items["Self"]) == []
    assert items["Author/CoreEngine"]["needed_by"] == ["User"]


def test_tag_parser_values():
    tags = rp.parse_header_tags(
        "/*:\r\n * @base  A \r\n * @orderAfter B */\r\n/*~struct~X:\n * @base C\n */"
    )
    assert tags == {"base": ["A"], "orderAfter": ["B"], "orderBefore": []}


def test_order_checks(tmp_path):
    root = make_game(
        tmp_path,
        [
            entry("Addon"),
            entry("Core"),
            entry("Patch"),
            entry("BaseUser"),
            entry("Base"),
            entry("OptUser"),
            entry("Optional", False),
        ],
    )
    write_plugin(root, "Addon", header("@orderAfter Core"))
    write_plugin(root, "Patch", header("@orderBefore Core"))
    write_plugin(root, "BaseUser", header("@base Base"))
    write_plugin(root, "OptUser", header("@orderAfter Optional"))
    items = by_name(rp.load_plugins(str(root)))
    assert items["Addon"]["issues"] == [  # pyright: ignore[reportGeneralTypeIssues]
        {
            "code": "wrong_order",
            "level": "warning",
            "direction": "after",
            "names": ["Core"],
        }
    ]
    assert items["Patch"]["issues"] == [  # pyright: ignore[reportGeneralTypeIssues]
        {
            "code": "wrong_order",
            "level": "warning",
            "direction": "before",
            "names": ["Core"],
        }
    ]
    assert codes(items["BaseUser"]) == []
    assert codes(items["OptUser"]) == []


def test_needed_by_and_takeover(tmp_path):
    names = [f"User{i}" for i in range(6)]
    root = make_game(tmp_path, [entry("CoreEngine"), *(entry(n) for n in names)])
    for name in names:
        write_plugin(root, name, header("@base CoreEngine"))
    items = by_name(rp.load_plugins(str(root)))
