    root2 = make_game(tmp_path / "t", [entry("A/Core"), entry("User"), entry("B/Core")])
    write_plugin(root2, "User", header("@base Core"))
    items = by_name(rp.load_plugins(str(root2)))
    assert items["A/Core"]["needed_by"] == []


