# ── 2.1 Switch ──


LAYOUTS = {
    "mv": plugins_text([entry("A"), entry("B", False)]),
    "mz": "// Generated by RPG Maker.\nvar $plugins =\n[\n"
    + json.dumps(entry("A"), ensure_ascii=False)
    + ",\n"
    + json.dumps(entry("B", False), ensure_ascii=False)
    + "\n];\n",
    "bom_crlf_jp": "\ufeff"
    + plugins_text(
        [
            entry("A", description="日本語"),
            entry("B", False, parameters={"x": '"status":true'}),
        ],
        "\r\n",
    ),
    "no_semicolon": 'var $plugins = [{"name":"A","status":true},{"name":"B","status":false}]',
}


@pytest.mark.parametrize("layout", sorted(LAYOUTS))
def test_switch_round_trip_is_byte_identical(tmp_path, layout):
    root = make_game(tmp_path, [entry("A"), entry("B", False)])
    path = root / "js" / "plugins.js"
    path.write_bytes(LAYOUTS[layout].encode("utf-8"))
    original = path.read_bytes()
    state = rp.load_plugins(str(root))
    state = rp.set_plugin_enabled(str(root), 0, False, str(state["revision"]))
    changed = path.read_bytes()
    assert changed != original
    assert len(changed) == len(original) + 1
    state = rp.set_plugin_enabled(str(root), 0, True, str(state["revision"]))
    state = rp.set_plugin_enabled(str(root), 1, True, str(state["revision"]))
    _ = rp.set_plugin_enabled(str(root), 1, False, str(state["revision"]))
    assert path.read_bytes() == original
    assert (root / "js" / "plugins.js.wlib-backup").read_bytes() == original


