def test_stale_revision_at_first_check(tmp_path):
    root = make_game(tmp_path, [entry("A")])
    path = root / "js" / "plugins.js"
    state = rp.load_plugins(str(root))
    path.write_text(plugins_text([entry("A"), entry("B")]), encoding="utf-8")
    before = path.read_bytes()
    with pytest.raises(StalePluginList):
        _ = rp.set_plugin_enabled(str(root), 0, False, str(state["revision"]))
    assert path.read_bytes() == before
    assert not (root / "js" / "plugins.js.wlib-backup").exists()


def test_stale_revision_before_replace(tmp_path, monkeypatch):
    root = make_game(tmp_path, [entry("A")])
    js = root / "js"
    path = js / "plugins.js"
    state = rp.load_plugins(str(root))
    real_replace = os.replace

    def replace(src, dst):
        if str(dst).endswith("plugins.js"):
            raise AssertionError("must not replace")
        real_replace(src, dst)

    real_check = rp._check_revision  # pyright: ignore[reportPrivateUsage]
    calls = {"n": 0}

    def check(js_dir, revision):
        calls["n"] += 1
        if calls["n"] == 3:
            path.write_text(plugins_text([entry("A"), entry("Z")]), encoding="utf-8")
        return real_check(js_dir, revision)

    monkeypatch.setattr(os, "replace", replace)
    monkeypatch.setattr(rp, "_check_revision", check)
    edited_backup = js / "plugins.js.wlib-backup"
    with pytest.raises(StalePluginList):
        _ = rp.set_plugin_enabled(str(root), 0, False, str(state["revision"]))
    assert "Z" in path.read_text(encoding="utf-8")
    assert edited_backup.exists()
    assert [p.name for p in js.iterdir() if p.name.startswith(".wlib-")] == []


def test_refused_switch_on_without_file(tmp_path):
    root = make_game(tmp_path, [entry("A", False)], files=())
    state = rp.load_plugins(str(root))
    with pytest.raises(PluginListError, match="cannot be switched on"):
        _ = rp.set_plugin_enabled(str(root), 0, True, str(state["revision"]))
    assert not (root / "js" / "plugins.js.wlib-backup").exists()


def test_failed_write_and_replace_keep_the_original(tmp_path, monkeypatch):
    root = make_game(tmp_path, [entry("A")])
    js = root / "js"
    path = js / "plugins.js"
    (js / "plugins.js.wlib-backup").write_bytes(path.read_bytes())
    original = path.read_bytes()
    state = rp.load_plugins(str(root))

    def fail_fsync(_fd):
        raise OSError(28, "No space left on device")

    monkeypatch.setattr(os, "fsync", fail_fsync)
    with pytest.raises(OSError, match="No space"):
        _ = rp.set_plugin_enabled(str(root), 0, False, str(state["revision"]))
    monkeypatch.undo()
    assert path.read_bytes() == original

    def fail_replace(_src, _dst):
        raise PermissionError(13, "File is in use")

    monkeypatch.setattr(os, "replace", fail_replace)
    with pytest.raises(PermissionError):
        _ = rp.set_plugin_enabled(str(root), 0, False, str(state["revision"]))
    monkeypatch.undo()
    assert path.read_bytes() == original
    assert [p.name for p in js.iterdir() if p.name.startswith(".wlib-")] == []


@pytest.mark.skipif(os.name == "nt", reason="POSIX permission bits")
def test_permission_bits_are_kept(tmp_path):
    root = make_game(tmp_path, [entry("A")])
    path = root / "js" / "plugins.js"
    path.chmod(0o640)
    state = rp.load_plugins(str(root))
    _ = rp.set_plugin_enabled(str(root), 0, False, str(state["revision"]))
    assert stat.S_IMODE(path.stat().st_mode) == 0o640
    backup = root / "js" / "plugins.js.wlib-backup"
    assert stat.S_IMODE(backup.stat().st_mode) == 0o640


# ── 2.2 Backup ──


def test_backup_made_once_and_never_overwritten(tmp_path):
    root = make_game(tmp_path, [entry("A"), entry("B")])
    path = root / "js" / "plugins.js"
    backup = root / "js" / "plugins.js.wlib-backup"
    original = path.read_bytes()
    state = rp.load_plugins(str(root))
    assert state["backup"]["state"] == "none"  # pyright: ignore[reportIndexIssue]
    # No-change switch: no backup.
    state = rp.set_plugin_enabled(str(root), 0, True, str(state["revision"]))
    assert not backup.exists()
    state = rp.set_plugin_enabled(str(root), 0, False, str(state["revision"]))
    assert backup.read_bytes() == original
    assert state["backup"]["state"] == "toggles"  # pyright: ignore[reportIndexIssue]
    state = rp.set_plugin_enabled(str(root), 1, False, str(state["revision"]))
    assert backup.read_bytes() == original
    state = rp.set_plugin_enabled(str(root), 0, True, str(state["revision"]))
    state = rp.set_plugin_enabled(str(root), 1, True, str(state["revision"]))
    assert state["backup"]["state"] == "same"  # pyright: ignore[reportIndexIssue]


def test_backup_write_failure_leaves_the_list(tmp_path, monkeypatch):
    root = make_game(tmp_path, [entry("A")])
    path = root / "js" / "plugins.js"
    original = path.read_bytes()
    state = rp.load_plugins(str(root))
    real_replace = os.replace

    def replace(src, dst):
        if str(dst).endswith(".wlib-backup"):
            raise OSError(28, "No space left on device")
        real_replace(src, dst)

    monkeypatch.setattr(os, "replace", replace)
    with pytest.raises(OSError, match="No space"):
        _ = rp.set_plugin_enabled(str(root), 0, False, str(state["revision"]))
    assert path.read_bytes() == original
    assert not (root / "js" / "plugins.js.wlib-backup").exists()


def test_backup_states(tmp_path):
    root = make_game(tmp_path, [entry("A"), entry("B")])
    js = root / "js"
    path = js / "plugins.js"
    backup = js / "plugins.js.wlib-backup"

    def state_of() -> dict[str, str]:
        return rp.load_plugins(str(root))["backup"]  # pyright: ignore[reportReturnType]

    assert state_of()["state"] == "none"
    backup.write_bytes(path.read_bytes())
    assert state_of()["state"] == "same"
    path.write_text(plugins_text([entry("A", False), entry("B")]), encoding="utf-8")
    assert state_of()["state"] == "toggles"
    path.write_text(
        plugins_text([entry("A"), entry("B"), entry("C")]), encoding="utf-8"
    )
    assert state_of()["state"] == "changed"
    path.write_text("broken", encoding="utf-8")
    assert state_of()["state"] == "changed"
    path.unlink()
    assert state_of()["state"] == "changed"
    backup.write_text("var $plugins = [", encoding="utf-8")
    result = state_of()
    assert result["state"] == "invalid"
    assert "not a readable plugin list" in result["reason"]


# ── 2.3 Restore ──


def test_restore_toggles_without_confirmation(tmp_path):
    root = make_game(tmp_path, [entry("A"), entry("B"), entry("C")])
    path = root / "js" / "plugins.js"
    original = path.read_bytes()
    state = rp.load_plugins(str(root))
    for index in range(3):
        state = rp.set_plugin_enabled(str(root), index, False, str(state["revision"]))
    state = rp.restore_plugins(str(root), str(state["revision"]), False)
    assert path.read_bytes() == original
    assert (root / "js" / "plugins.js.wlib-backup").read_bytes() == original
    assert state["backup"]["state"] == "same"  # pyright: ignore[reportIndexIssue]
    with pytest.raises(PluginListError, match="already equals"):
        _ = rp.restore_plugins(str(root), str(state["revision"]), True)


def test_restore_changed_needs_confirmation(tmp_path):
    root = make_game(tmp_path, [entry("A")])
    js = root / "js"
    path = js / "plugins.js"
    original = path.read_bytes()
    (js / "plugins.js.wlib-backup").write_bytes(original)
    path.write_text(plugins_text([entry("A"), entry("New")]), encoding="utf-8")
    updated = path.read_bytes()
    state = rp.load_plugins(str(root))
    with pytest.raises(PluginListError, match="Confirm"):
        _ = rp.restore_plugins(str(root), str(state["revision"]), False)
    assert path.read_bytes() == updated
    _ = rp.restore_plugins(str(root), str(state["revision"]), True)
    assert path.read_bytes() == original
    assert (js / "plugins.js.wlib-backup").exists()


@pytest.mark.parametrize("current", ["broken", None])
def test_restore_unreadable_or_missing_current(tmp_path, current):
    root = make_game(tmp_path, [entry("A")])
    js = root / "js"
    path = js / "plugins.js"
    original = path.read_bytes()
    (js / "plugins.js.wlib-backup").write_bytes(original)
    if current is None:
        path.unlink()
    else:
        path.write_text(current, encoding="utf-8")
    state = rp.load_plugins(str(root))
    assert state["readable"] is False
    assert state["backup"]["state"] == "changed"  # pyright: ignore[reportIndexIssue]
    state = rp.restore_plugins(str(root), str(state["revision"]), True)
    assert path.read_bytes() == original
    assert state["readable"] is True


def test_restore_refuses_invalid_backup_and_stale(tmp_path):
    root = make_game(tmp_path, [entry("A")])
    js = root / "js"
    (js / "plugins.js.wlib-backup").write_text("nope", encoding="utf-8")
    state = rp.load_plugins(str(root))
    with pytest.raises(PluginListError, match="not a readable"):
        _ = rp.restore_plugins(str(root), str(state["revision"]), True)
    (js / "plugins.js.wlib-backup").unlink()
    with pytest.raises(PluginListError, match="no plugin list backup"):
        _ = rp.restore_plugins(str(root), str(state["revision"]), True)
    with pytest.raises(StalePluginList):
        _ = rp.restore_plugins(str(root), "0" * 64, True)
    assert sha(js / "plugins.js") == state["revision"]
